# Initialize sequence
seq = [None] * length
for pos, val in fixed0.items():
    seq[pos] = val

# Apply deduced placements
# For each fixed, if only one possible other position, set it.
def deduce(seq):
    changed = True
    while changed:
        changed = False
        for pos, val in list(enumerate(seq)):
            if val is None:
                continue
            v = val
            other1 = pos - (v + 1)
            other2 = pos + (v + 1)
            valid_others = []
            for other in (other1, other2):
                if 0 <= other < length:
                    if seq[other] is None or seq[other] == v:
                        valid_others.append(other)
            if len(valid_others) == 0:
                return False  # impossible
            elif len(valid_others) == 1:
                other = valid_others[0]
                if seq[other] is None:
                    seq[other] = v
                    changed = True
                elif seq[other] != v:
                    return False
        # Also check for values that appear twice already: ensure distance correct.
    return True

