def get_valid_pairs(v, seq):
    pairs = get_possible_pairs(v, seq)
    existing = [i for i, val in enumerate(seq) if val == v]
    if len(existing) == 1:
        pos = existing[0]
        pairs = [(i,j) for (i,j) in pairs if i == pos or j == pos]
    elif len(existing) == 2:
        # Should not happen if we call this for values still needing placement
        return []
    return pairs

# Let's try to solve with backtracking
