solution = None
nodes = 0

def backtrack(seq, remaining):
    global solution, nodes
    nodes += 1
    if nodes % 10000 == 0:
        print(f"  nodes: {nodes}, remaining: {len(remaining)}")

    if not remaining:
        # Check complete
        if None not in seq:
            solution = seq[:]
            return True
        else:
            return False

    # Choose variable with fewest possible pairs (MRV)
    best_v = None
    best_pairs = None
    for v in remaining:
        pairs = get_valid_pairs(v, seq)
        if len(pairs) == 0:
            return False  # dead end
        if best_v is None or len(pairs) < len(best_pairs):
            best_v = v
            best_pairs = pairs
            if len(pairs) == 1:
                break  # can't get better than 1

    # Sort pairs maybe by some heuristic (e.g., least constraining)
    # For now, just iterate
    for i, j in best_pairs:
        # Check if positions are free (or already have this value)
        if seq[i] is not None and seq[i] != best_v:
            continue
        if seq[j] is not None and seq[j] != best_v:
            continue

        # Save old values
        old_i = seq[i]
        old_j = seq[j]

        # Place
        seq[i] = best_v
        seq[j] = best_v

        # Propagate (simple forward checking: just check consistency)
        # Actually, we can do full propagation
        # But let's just check that no value loses all possibilities
        # For efficiency, we'll just recurse and let the next level check.

        new_remaining = [v for v in remaining if v != best_v]

        # Quick check: for each remaining value, ensure at least one pair exists
        possible = True
        for v in new_remaining:
            if len(get_valid_pairs(v, seq)) == 0:
                possible = False
                break
        if possible:
            if backtrack(seq, new_remaining):
                return True

        # Backtrack
        seq[i] = old_i
        seq[j] = old_j

    return False

